using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class AndroidResearchResultCardFileStore{private readonly string _path;public AndroidResearchResultCardFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(AndroidResearchResultCard value){if(value.CanSubmitOrders)throw new InvalidOperationException("Research result card cannot grant order authority.");Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public AndroidResearchResultCard Load(){var v=JsonSerializer.Deserialize<AndroidResearchResultCard>(File.ReadAllText(_path))??throw new InvalidOperationException("Result card JSON is invalid.");if(v.CanSubmitOrders)throw new InvalidOperationException("Persisted result card grants order authority.");return v;}}
